<?php
declare(strict_types=1);requireRole('social-service-officer');require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/activity.php';require_once __DIR__.'/../../includes/eligibility.php';$activePage='pending-handover';$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);$db=database();$userId=(int)$_SESSION['user_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){$id=filter_input(INPUT_POST,'handover_id',FILTER_VALIDATE_INT);if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired.';if(!$id)$errors[]='Invalid handover.';if(!$errors){try{$db->beginTransaction();$stmt=$db->prepare("SELECT * FROM vision_camp_handovers WHERE id=:id AND officer_id=:user AND status='pending' FOR UPDATE");$stmt->execute(['id'=>$id,'user'=>$userId]);$handover=$stmt->fetch();if(!$handover)throw new RuntimeException('Handover is no longer pending.');$eligibility=beneficiaryEligibility($db,(int)$handover['beneficiary_id'],(int)$handover['item_id']);if(!$eligibility['eligible'])throw new RuntimeException($eligibility['reason']);$insert=$db->prepare("INSERT INTO distributions(beneficiary_id,item_id,quantity,distribution_type,source,distributed_by) VALUES(:beneficiary,:item,:quantity,'direct','vision-camp',:user)");$insert->execute(['beneficiary'=>$handover['beneficiary_id'],'item'=>$handover['item_id'],'quantity'=>$handover['quantity'],'user'=>$userId]);$distributionId=(int)$db->lastInsertId();$db->prepare("UPDATE vision_camp_handovers SET status='distributed',distributed_at=NOW() WHERE id=:id")->execute(['id'=>$id]);$db->commit();logActivity('Vision Handover','Distributed vision camp handover','DIST-'.str_pad((string)$distributionId,4,'0',STR_PAD_LEFT),'vision-camp');$_SESSION['flash_success']='Handover marked distributed and beneficiary history updated.';unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=pending-handover');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log($e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to distribute handover.';}}}
try{$stmt=$db->prepare('SELECT h.*,b.full_name,b.nic,i.item_name,i.variety,u.full_name handed_name FROM vision_camp_handovers h JOIN beneficiaries b ON b.id=h.beneficiary_id JOIN inventory_items i ON i.id=h.item_id JOIN users u ON u.id=h.handed_by WHERE h.officer_id=:user ORDER BY h.id DESC');$stmt->execute(['user'=>$userId]);$rows=$stmt->fetchAll();}catch(PDOException $e){error_log($e->getMessage());$rows=[];$errors[]='Vision handovers are unavailable.';}$counts=array_count_values(array_column($rows,'status'));
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pending Handover | WIDMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body><?php require __DIR__.'/../../includes/social-service-officer-sidebar.php';?><div class="admin-shell"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-button" id="menu-button">&#9776;</button><h1>Pending Handover</h1></div></header><main class="dashboard-content"><?php if($success):?><div class="alert alert-success"><?=$success?></div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=htmlspecialchars(implode(' ',$errors),ENT_QUOTES,'UTF-8')?></div><?php endif;?><section class="handover-summary-grid"><article class="handover-summary-card pending"><span class="handover-summary-icon">&#128083;</span><p>Pending Handover Items</p><strong><?=(int)($counts['pending']??0)?></strong><small>Awaiting distribution by you</small></article><article class="handover-summary-card distributed"><span class="handover-summary-icon">&#9989;</span><p>Already Distributed</p><strong><?=(int)($counts['distributed']??0)?></strong><small>From handovers</small></article><article class="handover-summary-card received"><span class="handover-summary-icon">&#128230;</span><p>Total Received</p><strong><?=count($rows)?></strong><small>All-time handovers</small></article></section><section class="handover-list-card"><div class="handover-list-header"><h2>Vision Camp Leftover Items</h2></div><div class="handover-table-wrap"><table class="handover-table"><thead><tr><th>ID</th><th>Item</th><th>Source Camp</th><th>Beneficiary</th><th>Handed Over By</th><th>Date</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8" class="handover-empty">No vision camp handovers available.</td></tr><?php else:foreach($rows as $r):?><tr><td>HO-<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?></td><td><?=htmlspecialchars($r['item_name'].($r['variety']?' — '.$r['variety']:''),ENT_QUOTES,'UTF-8')?> × <?=(int)$r['quantity']?></td><td>VC-<?=str_pad((string)$r['camp_id'],4,'0',STR_PAD_LEFT)?></td><td><?=htmlspecialchars($r['full_name'].' — '.$r['nic'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['handed_name'],ENT_QUOTES,'UTF-8')?></td><td><?=date('d M Y',strtotime($r['handed_at']))?></td><td><?=ucfirst($r['status'])?></td><td><?php if($r['status']==='pending'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="handover_id" value="<?=(int)$r['id']?>"><button class="approve-button">Mark Distributed</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><script src="assets/js/admin-dashboard.js"></script></body></html>
